import { languages, openGraphLocale, siteUrl, type Language } from "../lib/site";
import { getPageData, type PageData } from "../lib/page-data";

export type RouteRegion = "Europe" | "Asia" | "Americas" | "Africa" | "Oceania";
export type RouteDifficulty = "easy" | "medium" | "hard";
export type LandmarkType = "religious" | "historical" | "natural" | "cultural";

interface CityFact { name: string; country: string; km: number; note: string; }
interface LandmarkFact { name: string; type: LandmarkType; note: string; }
interface RouteFact {
  slug: string;
  name: string;
  region: RouteRegion;
  countries: string[];
  distanceKm: number;
  difficulty: RouteDifficulty;
  story: string;
  cities: CityFact[];
  landmarks: LandmarkFact[];
  signature: string[];
  stamps: number;
  isFree: boolean;
  sources: Array<{ title: string; url: string }>;
}

export interface RouteTranslation {
  name: string;
  title: string;
  metaDescription: string;
  description: string;
  alt: string;
  highlights: string[];
  cityDescriptions: string[];
  landmarkDescriptions: string[];
}

export interface RouteData extends RouteFact {
  image: string;
  imageCredit: string;
  weeks: number;
  translations: Record<string, RouteTranslation>;
}

const city = (name: string, country: string, km: number, note: string): CityFact => ({ name, country, km, note });
const mark = (name: string, type: LandmarkType, note: string): LandmarkFact => ({ name, type, note });

