  ja: { journey: "バーチャル徒歩旅行", explore: "巡る", through: "を通る", route: "ルート", distance: "距離", highlights: "見どころ", cities: "都市と節目", landmarks: "名所", stats: "ルート情報", weeks: "1日1万歩での週数", difficulty: "難易度", stamps: "収集スタンプ", free: "無料ルート", premium: "プレミアルート", open: "WalkQuestで開く", related: "関連ルート", sources: "参考資料", imageCredit: "ヒーロー画像：OpenAIがWalkQuest向けに制作したオリジナルイラスト。", home: "ホーム", allRoutes: "ルート", cityNote: (c,country,km) => `${c}は${country}の${km}km地点。旅に固有の地域物語を加える節目です。`, landmarkNote: (n,t) => `${n}を${t}の名所として、その区間の背景とともに紹介します。`, describe: (n,d,c,cs,s,w) => `${n}は、${c}を舞台にした全長${d}kmのバーチャル徒歩旅行です。${cs}を結び、実在の地理と確認された文化遺産を長期的な冒険へ変えます。代表的な章は${s}です。1日1万歩なら全行程は約${w}週間。各節目で歴史・文化・自然の背景が開き、デジタルスタンプが進捗を見える形にします。安全で歩きやすい場所を選べば、Health Connectの歩数が海越えや山岳区間、長距離移動を含む仮想地図を進めます。` },
