const titleSuffix: Record<string, string> = { en: "Virtual Walking Route | WalkQuest", uk: "віртуальний маршрут | WalkQuest", ru: "виртуальный маршрут | WalkQuest", es: "ruta virtual | WalkQuest", de: "virtuelle Route | WalkQuest", fr: "parcours virtuel | WalkQuest", pl: "wirtualna trasa | WalkQuest", pt: "rota virtual | WalkQuest", "pt-BR": "rota virtual | WalkQuest", it: "percorso virtuale | WalkQuest", tr: "sanal rota | WalkQuest", ja: "バーチャル徒歩ルート | WalkQuest", ko: "가상 도보 경로 | WalkQuest", "zh-CN": "虚拟徒步路线 | WalkQuest", ar: "مسار مشي افتراضي | WalkQuest", hi: "आभासी पैदल मार्ग | WalkQuest" };

function compactTitle(name: string, locale: string): string {
  const full = `${name}: ${titleSuffix[locale]}`;
  return full.length <= 65 ? full : `${name} | WalkQuest`;
}

function metaDescription(name: string, distance: number, locale: string): string {
  const pack = localePacks[locale];
  const raw = locale === "en"
    ? `Explore ${name}, a ${distance.toLocaleString("en")} km virtual walking route with real cities, landmarks and collectible stamps. Start your WalkQuest journey today.`
    : `${pack.explore} ${name}: ${pack.journey.toLowerCase()}, ${distance.toLocaleString(locale)} km. ${pack.cities}, ${pack.landmarks}, ${pack.stamps}. ${pack.open}.`;
  return raw.length > 160 ? `${raw.slice(0, 157).replace(/\s+\S*$/, "")}…` : raw;
}

function landmarkForCity(fact: RouteFact, cityIndex: number): LandmarkFact {
  const cityName = fact.cities[cityIndex].name.toLocaleLowerCase("en");
  const direct = fact.landmarks.find((landmark) => {
    const landmarkName = landmark.name.toLocaleLowerCase("en");
    return landmarkName.includes(cityName) || cityName.includes(landmarkName.split(/\s+/)[0]);
  });
  return direct ?? fact.landmarks[Math.min(fact.landmarks.length - 1, Math.floor(cityIndex * fact.landmarks.length / fact.cities.length))];
}

function buildTranslation(fact: RouteFact, language: Language, weeks: number): RouteTranslation {
  const locale = language.code;
  const pack = localePacks[locale];
  const name = routeNameTranslations[fact.slug]?.[locale] ?? fact.name;
  const countryList = fact.countries.join(", ");
  const cityList = fact.cities.slice(0, 4).map((item) => item.name).join(", ");
  const signature = fact.landmarks.slice(0, 3).map((item) => item.name).join(", ");
  const generated = pack.describe(name, fact.distanceKm, countryList, cityList, signature, weeks);
  const description = locale === "en" ? `${fact.story} ${generated}` : generated;
  return {
    name,
    title: compactTitle(name, locale),
    metaDescription: metaDescription(name, fact.distanceKm, locale),
    description,
    alt: locale === "en" ? `Illustrated ${fact.name} route panorama with landmarks and a dotted walking path` : `${name}: ${pack.journey.toLowerCase()} — ${pack.landmarks}, ${pack.route}`,
    highlights: [
      `${pack.explore} ${fact.cities[0].name}, ${fact.cities[1].name} ${pack.through} ${fact.cities.at(-1)!.name}`,
      `${fact.distanceKm.toLocaleString("en")} km · ${weeks} ${pack.weeks}`,
      `${pack.route}: ${countryList}`,
      `${pack.landmarks}: ${fact.landmarks.slice(0, 3).map((item) => item.name).join(", ")}`,
      `${pack.cities}: ${fact.cities.slice(2, 6).map((item) => item.name).join(", ")}`,
      `${pack.stamps}: ${fact.stamps}`
    ],
    cityDescriptions: fact.cities.map((item, index) => locale === "en" ? item.note : cityContexts[locale](
      item.name,
      item.country,
      item.km,
      name,
      fact.cities[Math.max(0, index - 1)].name,
      fact.cities[Math.min(fact.cities.length - 1, index + 1)].name,
      landmarkForCity(fact, index).name,
      index,
      index === fact.cities.length - 1
    )),
    landmarkDescriptions: fact.landmarks.map((item, index) => locale === "en" ? item.note : landmarkContexts[locale](
      item.name,
      categoryLabels[locale][item.type],
      name,
      fact.cities[Math.min(fact.cities.length - 1, Math.round(index * (fact.cities.length - 1) / Math.max(1, fact.landmarks.length - 1)))].name,
      index
    ))
  };
}

export const newRoutes: RouteData[] = facts.map((fact) => {
  const weeks = Math.max(1, Math.round(fact.distanceKm / 52.5));
  return {
    ...fact,
    weeks,
    image: `/images/routes/${fact.slug}.webp`,
    imageCredit: "AI-generated original artwork by OpenAI for WalkQuest",
    translations: Object.fromEntries(languages.map((language) => [language.code, buildTranslation(fact, language, weeks)]))
  };
});

export function routeBySlug(slug: string): RouteData {
  const route = newRoutes.find((item) => item.slug === slug);
  if (!route) throw new Error(`Unknown new route: ${slug}`);
  return route;
}

export function languageForCode(code: string): Language {
  return languages.find((language) => language.code === code) ?? languages[0];
}

export function localizedRoutePath(route: RouteData, language: Language): string {
  return language.code === "en" ? `/routes/${route.slug}.html` : `/${language.slug}/routes/${route.slug}.html`;
}

export function routePageData(route: RouteData, language: Language): PageData {
  const t = route.translations[language.code];
  const path = localizedRoutePath(route, language);
  const url = `${siteUrl}${path}`;
  const alternates = [...languages.map((item) => ({ lang: item.code, href: `${siteUrl}${localizedRoutePath(route, item)}` })), { lang: "x-default", href: `${siteUrl}${localizedRoutePath(route, languages[0])}` }];
  const imageUrl = `${siteUrl}${route.image}`;
  const itinerary = route.cities.map((item, index) => ({ "@type": "ListItem", position: index + 1, name: item.name, description: t.cityDescriptions[index] }));
  const basePage = getPageData(language.code === "en" ? "routes.html" : `${language.slug}/routes.html`);
  return {
    relativePath: path.slice(1), lang: language.code, dir: language.dir,
    bodyAttributes: { class: "info-site route-detail-site new-route-site", "data-nav-page": "routes" },
    labels: basePage.labels,
    head: {
      charset: "utf-8", title: t.title, description: t.metaDescription, robots: "index, follow", imageCredit: route.imageCredit, canonical: url, alternates,
      icon: { href: "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect width='64' height='64' rx='16' fill='%23082f36'/%3E%3Cpath d='M16 43c10-19 22-7 32-25' fill='none' stroke='%23ffd166' stroke-width='6' stroke-linecap='round' stroke-dasharray='2 10'/%3E%3Ccircle cx='48' cy='18' r='7' fill='%23ff6b4a'/%3E%3Ccircle cx='16' cy='43' r='6' fill='%2377dfb3'/%3E%3C/svg%3E", type: "image/svg+xml" },
      preconnects: [], stylesheets: ["/styles.css", "/pages.css?v=5"],
      openGraph: { title: t.title, description: t.metaDescription, image: imageUrl, imageAlt: t.alt, imageWidth: "1200", imageHeight: "630", url, type: "article", siteName: "WalkQuest", locale: openGraphLocale(language.code) },
      twitter: { card: "summary_large_image", title: t.title, description: t.metaDescription, image: imageUrl, url },
      structuredData: [
        { "@context": "https://schema.org", "@type": "TouristTrip", name: t.name, description: t.description, url, image: imageUrl, touristType: "Virtual walkers and fitness game players", itinerary: { "@type": "ItemList", numberOfItems: itinerary.length, itemListElement: itinerary }, inLanguage: language.code },
        { "@context": "https://schema.org", "@type": "BreadcrumbList", itemListElement: [{ "@type": "ListItem", position: 1, name: localePacks[language.code].home, item: `${siteUrl}${language.code === "en" ? "/" : `/${language.slug}/`}` }, { "@type": "ListItem", position: 2, name: localePacks[language.code].allRoutes, item: `${siteUrl}${language.code === "en" ? "/routes.html" : `/${language.slug}/routes.html`}` }, { "@type": "ListItem", position: 3, name: t.name, item: url }] },
        { "@context": "https://schema.org", "@type": "ImageObject", contentUrl: imageUrl, url: imageUrl, caption: t.alt, creditText: route.imageCredit, creator: { "@type": "Organization", name: "OpenAI" } }
      ], scripts: [], inlineStyles: []
    }, chrome: "site", bodyScripts: [{ src: "/pages.js", defer: false }],
  };
}

export function labelsFor(locale: string) {
  return { ...localePacks[locale], difficultyText: difficultyLabels[locale], regionText: regionLabels[locale], categoryText: categoryLabels[locale] };
}
